  ('41273ca1-9faf-4d4b-82ae-de60ef8d36e2', 'sw-az-gti', 'sky-watcher', 'montur', 'AZ-GTi', 'Wi-Fi üzerinden telefonla kontrol edilen taşınabilir GoTo; ekvatoryal moda dönüştürülebilir.', 'Giriş segment', NULL, NULL, NULL, NULL, NULL, '5.00', '1.300', NULL, '{"Tip": "Altazimut (GoTo, Wi-Fi)"}', '{"Altazimut modda uzun poz alan dönmesi yapar; derin uzay için EQ modu ve kama gerekir."}', NULL, 'true', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'bilinmiyor', NULL, NULL, '[]', NULL, NULL, NULL),
  ('37f772bd-a906-4135-bf01-32e41d340f56', 'sw-eq6r-pro', 'sky-watcher', 'montur', 'EQ6-R Pro', '20 kg nominal kapasiteli belt-drive ekvatoryal montür. Orta sınıf astrofotoğrafın omurgası; 8–10 kg''lık kurulumları rahat taşır.', 'Üst segment', NULL, NULL, NULL, NULL, NULL, '20.00', '17.700', NULL, '{"Tip": "Ekvatoryal (GoTo)"}', '{"Görüntüleme için gerçekçi yük sınırı ~12 kg (nominal kapasitenin %60''ı).","17.7 kg gövde ağırlığı sahaya taşımayı tek başına zorlaştırır."}', NULL, 'true', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'bilinmiyor', NULL, NULL, '[]', NULL, NULL, NULL),
  ('a198b74c-18e3-440f-9107-0d2ad098095c', 'sw-eq8-r-pro', 'sky-watcher', 'montur', 'EQ8-R Pro', 'Sabit gözlemevi sınıfı montür. 50 kg kapasite, uzun odaklı büyük açıklıkları taşır; taşınabilirlik hedeflenmemiştir.', 'Profesyonel', NULL, NULL, NULL, NULL, NULL, '50.00', '25.500', NULL, '{"Tip": "Ekvatoryal (GoTo)"}', '{"25.5 kg gövde tek kişiyle taşınmaz; sabit kurulum içindir."}', NULL, 'true', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'bilinmiyor', NULL, NULL, '[]', NULL, NULL, NULL),
  ('d2f3d2ce-1c78-4e30-adba-31433dceb94b', 'sw-esprit-100', 'sky-watcher', 'optik-tup', 'Esprit 100ED', 'Üçlü apokromatik cam, tam kare sensörü dolduran düz alan ve 550 mm odak: kısa odak geniş alanla uzun odak detayı arasında en dengeli aralık.', 'Üst segment', '550.00', '100.00', NULL, NULL, NULL, NULL, NULL, NULL, '{"f/": "5.5", "Tip": "Üçlü APO"}', '{"Standart backfocus 55 mm — flattener ile birlikte satılır.","6.4 kg tüp ağırlığı, görüntüleme için en az 13 kg sınıfı montür ister."}', NULL, 'true', NULL, 'M48x0.75', NULL, '44.00', NULL, '55.00', NULL, NULL, NULL, NULL, 'guncel', NULL, NULL, '[]', NULL, 'tek-kaynak', NULL),
  ('67c09e76-b8a6-45fa-9846-277af57470a1', 'sw-esprit-120', 'sky-watcher', 'optik-tup', 'Esprit 120ED', '840 mm odakta üçlü apokromat: galaksi ve gezegenimsi bulutsu gibi küçük hedeflerde ölçek verirken tam kare sensörü düz alanla doldurur.', 'Üst segment', '840.00', '120.00', NULL, NULL, NULL, NULL, NULL, NULL, '{"f/": "7", "Tip": "Üçlü APO"}', '{"Yaklaşık 9 kg tüp ağırlığı, görüntüleme için 20 kg sınıfı montür ister.","Uzun odak, guiding hassasiyetini doğrudan artırır — OAG önerilir."}', NULL, 'true', NULL, 'M48x0.75', NULL, '44.00', NULL, '55.00', NULL, NULL, NULL, NULL, 'guncel', NULL, NULL, '[]', NULL, 'tek-kaynak', NULL),
  ('edb597d0-ced9-4b6e-89f4-50b18e80c4b8', 'sw-evostar-72ed', 'sky-watcher', 'optik-tup', 'Evostar 72ED', 'İlk astrograf olarak en sık önerilen ikili ED refraktör. 420 mm odak geniş alan verir, 2 kg ağırlık taşınabilir montürlerle çalışır.', 'Giriş segment', '420.00', '72.00', NULL, NULL, NULL, NULL, NULL, NULL, '{"f/": "5.8", "Tip": "İkili ED"}', '{"Düz alan için ayrı flattener gerekir; düzelticisiz köşelerde bozulma belirgindir.","İkili cam, üçlü APO kadar renk düzeltmesi vermez — parlak yıldızlarda hafif mor hâle görülebilir."}', NULL, 'true', NULL, '2in', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'guncel', NULL, NULL, '[]', NULL, 'tek-kaynak', NULL),
  ('c3e56eb0-c7ad-4adb-ab30-458741dd09a0', 'sw-evostar-80ed', 'sky-watcher', 'optik-tup', 'Evostar 80ED', 'ED camlı ikili apokromatik; 600 mm odakla hem orta boy bulutsulara hem küçük galaksilere yeter. Astrofoto için 0.85x reducer ile 510 mm f/6.4''e iner.', 'Giriş segment', '600.00', '80.00', NULL, NULL, NULL, NULL, '3.600', NULL, '{"f/": "7.5", "Tip": "İkili ED", "Backfocus": "55 mm"}', '{"Reducer olmadan kadraj köşelerinde alan eğriliği görünür.","Odaklayıcı standart 2 inç; ağır kamera yükünde sarkma yapabilir."}', NULL, 'true', NULL, '2in', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'guncel', NULL, NULL, '[]', NULL, 'tek-kaynak', NULL),
  ('f382ef68-8730-4850-bbb2-343c6a271dfc', 'sw-heq5-pro', 'sky-watcher', 'montur', 'HEQ5 Pro', 'Astrofotoğrafa giriş montürünün klasiği. 11 kg nominal kapasiteyle 5–6 kg’lık görüntüleme kurulumlarını taşır ve tek kişi sahaya götürebilir.', 'Orta segment', NULL, NULL, NULL, NULL, NULL, '11.00', '9.700', NULL, '{"Tip": "Ekvatoryal (GoTo)"}', '{"Görüntülemede gerçekçi sınır ~6.5 kg (nominalin %60’ı).","Belt-drive dönüşümü periyodik hatayı belirgin düşürür."}', NULL, 'true', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'bilinmiyor', NULL, NULL, '[]', NULL, NULL, NULL),
  ('2394217e-6d60-47fe-9f23-d9da8c5a040e', 'sw-quattro-150p', 'sky-watcher', 'optik-tup', 'Quattro 150P', 'f/4 hızında 6 inç Newton. Aynı açıklıkta apokromat fiyatının çok altında; karşılığında kolimasyon ve koma düzeltici disiplini ister.', 'Orta segment', '600.00', '150.00', NULL, NULL, NULL, NULL, NULL, NULL, '{"f/": "4", "Tip": "Newton"}', '{"Aplanatik koma düzeltici zorunludur.","Açık tüp, çiylenme ve toz açısından refraktörden hassastır."}', NULL, 'true', NULL, '2in', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'guncel', NULL, NULL, '[]', NULL, 'tek-kaynak', NULL),
  ('15960daf-1ada-4697-8d44-2f97ea47cc6a', 'sw-reducer-085x', 'sky-watcher', 'reducer', '0.85x Reducer/Corrector', 'Evostar 80ED için hem odak kısaltıcı hem alan düzleştirici.', 'Giriş segment', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"Uyum": "Evostar 80ED", "Çarpan": "0.85x", "Sonuç f/": "6.4", "Sonuç odak": "510 mm"}', '{}', NULL, 'true', '2in', 'M48x0.75', NULL, NULL, NULL, '55.00', NULL, '0.850', NULL, NULL, 'guncel', NULL, NULL, '[]', NULL, 'tek-kaynak', NULL),
  ('65034828-a328-44bb-80db-303232ce96ad', 'sw-star-adventurer-gti', 'sky-watcher', 'montur', 'Star Adventurer GTi', 'Sırt çantasına giren GoTo takip montürü. Kamera + kısa odak lens ya da hafif bir astrograf için tasarlandı.', 'Giriş segment', NULL, NULL, NULL, NULL, NULL, '5.00', '2.600', NULL, '{"Tip": "Taşınabilir GoTo"}', '{"5 kg nominal kapasite; görüntülemede 2.5–3 kg''ı geçmemek gerekir.","Geniş alan ve Samanyolu çekimleri için yeterli."}', NULL, 'true', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'bilinmiyor', NULL, NULL, '[]', NULL, NULL, NULL),
