  ('18941ecd-d3bb-4f09-a49c-e1cff3ab4160', 'sh2-240', 'Spagetti Bulutsusu', 'Sh2-240', 'sungerimsi-kalinti', 'Boğa', '85.65000', '28.00000', NULL, '180.00', '180.00', NULL, NULL, NULL, NULL, 'Boğa takımyıldızında, kataloglarda kadir değeri verilmeyen bir süpernova kalıntısı. 3.0° genişliğinde geniş bir alan kaplar. Gökyüzünün en sönük geniş kalıntılarından; onlarca saat toplam süre ister.'),
  ('d03afa99-5c3d-4f3c-a50f-eed9ed31f17b', 'uranus', 'Uranüs', 'Uranüs', 'gezegen', '—', NULL, NULL, NULL, '0.06', '0.06', NULL, NULL, NULL, NULL, 'Uranüs — konumu tarihe göre değişir; çekim penceresi için efemeris gerekir.'),
  ('c2d14bd5-07f9-455d-a264-bfa6d492aa92', 'venus', 'Venüs', 'Venüs', 'gezegen', '—', NULL, NULL, NULL, '1.00', '1.00', NULL, NULL, NULL, NULL, 'Venüs — konumu tarihe göre değişir. UV filtresi bulut yapısını ortaya çıkarır; görünür ışıkta düz beyaz bir disk kalır.')
